# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.14.0/ankra-cli-darwin-arm64"
      sha256 "c40b4c10913d15a805e152e40c333135f12b7fe50f16d3a6e1b67f3d69feee46"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.14.0/ankra-cli-darwin-amd64"
      sha256 "e5fa985eb55c3e1aba6ccc57b1f5a70bc6cc02eb00358688089284a67e64dcde"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.14.0/ankra-cli-linux-arm64"
      sha256 "76654b132dcae8da962379a0f110741e7391b76eb431877281cc551afd49c067"
    end
    on_intel do
